CREATE TABLE COMUNI_ITALIANI 
   (	CODICECOMUNE VARCHAR(5), 
	COMUNE VARCHAR(128), 
	SIGLAPROVINCIA VARCHAR(2), 
	PROVINCIA VARCHAR(20), 
	REGIONE VARCHAR(25), 
	CAP VARCHAR(5), 
	CF VARCHAR(5), 
	CODICEISTAT VARCHAR(6), 
	CODICEISTATREGIONE VARCHAR(2), 
	CODICESTATOESTERO VARCHAR(3)
   ) ENGINE=INNODB DEFAULT CHARSET=utf8;
 
 ALTER TABLE COMUNI_ITALIANI ADD CONSTRAINT PK_COMUNI_ITALIANI PRIMARY KEY (CODICECOMUNE);
 
 
